#!/usr/bin/env bash
set -e

REPO="$(pwd)"
if [ ! -f "$REPO/main.py" ] || [ ! -d "$REPO/app" ]; then
  echo "ERROR: Run this script from inside your watchly-trakt directory."
  exit 1
fi
echo "Applying Trakt integration patch..."
mkdir -p "$REPO/app/services/trakt"

mkdir -p "$REPO/app/services/trakt"
echo "ZnJvbSBhcHAuc2VydmljZXMudHJha3Quc2VydmljZSBpbXBvcnQgVHJha3RCdW5kbGUKCl9fYWxsX18gPSBbIlRyYWt0QnVuZGxlIl0K" | base64 --decode > "$REPO/app/services/trakt/__init__.py"
echo "  wrote app/services/trakt/__init__.py"

mkdir -p "$REPO/app/services/trakt"
echo "" | base64 --decode > "$REPO/app/services/trakt/client.py"
echo "  wrote app/services/trakt/client.py"

mkdir -p "$REPO/app/services/trakt"
echo "" | base64 --decode > "$REPO/app/services/trakt/auth.py"
echo "  wrote app/services/trakt/auth.py"

mkdir -p "$REPO/app/services/trakt"
echo "" | base64 --decode > "$REPO/app/services/trakt/user.py"
echo "  wrote app/services/trakt/user.py"

mkdir -p "$REPO/app/services/trakt"
echo "" | base64 --decode > "$REPO/app/services/trakt/library.py"
echo "  wrote app/services/trakt/library.py"

mkdir -p "$REPO/app/services/trakt"
echo "" | base64 --decode > "$REPO/app/services/trakt/service.py"
echo "  wrote app/services/trakt/service.py"

mkdir -p "$REPO/app/api/endpoints"
echo "" | base64 --decode > "$REPO/app/api/endpoints/trakt.py"
echo "  wrote app/api/endpoints/trakt.py"

mkdir -p "$REPO/app/static/js/modules"
