echo "  wrote app/static/js/modules/trakt.js"

mkdir -p "$REPO/app/templates/components"
echo "" | base64 --decode > "$REPO/app/templates/components/section_login.html"
echo "  wrote app/templates/components/section_login.html"

mkdir -p "$REPO/app/api"
echo "" | base64 --decode > "$REPO/app/api/router.py"
echo "  wrote app/api/router.py"

mkdir -p "$REPO/app/core"
echo "" | base64 --decode > "$REPO/app/core/config.py"
