mkdir -p "$REPO/app/services"
echo "" | base64 --decode > "$REPO/app/services/manifest.py"
echo "  wrote app/services/manifest.py"

mkdir -p "$REPO/app/services"
echo "" | base64 --decode > "$REPO/app/services/catalog_updater.py"
echo "  wrote app/services/catalog_updater.py"

mkdir -p "$REPO/app/services"
echo "" | base64 --decode > "$REPO/app/services/token_store.py"
echo "  wrote app/services/token_store.py"

cat >> "$REPO/.env.example" << 'ENVEOF'

# Trakt OAuth (optional - enables Trakt login on the configure page)
# Register your app at https://trakt.tv/oauth/applications/new
# Set the redirect URI to: http://localhost:8000/tokens/trakt/callback
TRAKT_CLIENT_ID=
